@pytest.mark.parametrize("context", [
    {"user_agent": "Mobile Browser", "viewport_width": 390,
     "viewport_height": 844, "locale": "en-US"},
    {"viewport_width": 0, "locale": ""},
    {},
    None,
])
def test_enrich_event_client_context(context):
    from copy import deepcopy
    from pipeline.enricher import enrich_event

    base = {"event_id": "e1", "event_type": "view",
            "timestamp": "2026-01-01T00:00:00Z", "session_id": "s1"}
    raw = {**base, "client_context": context, "user_email": "ignored@example.test"}
    if context is not None:
        raw["client_context"] = {**context, "phone_number": "not-for-storage"}
    original = deepcopy(raw)
    enriched = enrich_event(raw)
    expected = {**base, **{field: (context or {}).get(field) for field in (
        "user_agent", "viewport_width", "viewport_height", "locale"
    )}}
    assert enriched == expected
    assert raw == original


def test_enrich_event_without_client_context():
    from pipeline.enricher import enrich_batch, enrich_event

    raw = {"event_id": "e1", "event_type": "click",
           "timestamp": "2026-01-01T00:00:00Z", "session_id": "s1"}
    enriched = enrich_event(raw)
    assert all(enriched[field] is None for field in (
        "user_agent", "viewport_width", "viewport_height", "locale"
    ))
    assert enrich_batch([]) == []


def test_processor_persists_enriched_batch(tmp_path, monkeypatch):
    import json
    from pipeline import processor

    target = tmp_path / "analytics_events.jsonl"
    monkeypatch.setattr(processor, "append_events",
                        lambda records: append_events(records, target_file=target))
    base = {"event_type": "view", "timestamp": "2026-01-01T00:00:00Z",
            "session_id": "s1"}
    context = {"user_agent": "Desktop Browser", "viewport_width": 1440,
               "viewport_height": 900, "locale": "en-GB"}
    payload = {"events": [
        {**base, "event_id": "e1", "client_context": context},
        {**base, "event_id": "e2"},
    ]}
    assert processor.process_inbound_batch(payload) == 2
    lines = target.read_text().splitlines()
    assert len(lines) == 2
    assert json.loads(lines[0]) == {**base, "event_id": "e1", **context}
    assert json.loads(lines[1]) == {
        **base, "event_id": "e2", **dict.fromkeys(context)
    }
    assert processor.process_inbound_batch({"events": []}) == 0
    assert processor.process_inbound_batch({}) == 0
    assert len(target.read_text().splitlines()) == 2
PY
